# WattsTap API - Примеры интеграции для Unity

##  Установка и настройка

### 1. Создание API Service в Unity

```csharp
// Assets/WattsTap/Scripts/Core/API/WattsTapAPIService.cs
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Networking;
using Newtonsoft.Json;

namespace WattsTap.Core.API
{
    public interface IWattsTapAPIService : IService
    {
        IEnumerator Authenticate(string initData, Action<AuthResponse> onSuccess, Action<string> onError);
        IEnumerator SendTapBatch(List<TapData> taps, Action<TapBatchResponse> onSuccess, Action<string> onError);
        IEnumerator GetPlayerData(Action<PlayerData> onSuccess, Action<string> onError);
        IEnumerator SyncGameState(Action<SyncResponse> onSuccess, Action<string> onError);
        IEnumerator ClaimOfflineBonus(Action<OfflineRewards> onSuccess, Action<string> onError);
    }

    public class WattsTapAPIService : IWattsTapAPIService
    {
        private const string BASE_URL = "https://api.wattstap.com/v1";
        private string _authToken;
        private string _sessionId;

        public int InitializationOrder => 5;

        public void Initialize()
        {
            _sessionId = Guid.NewGuid().ToString();
            Debug.Log($"[WattsTapAPI] Service initialized with session: {_sessionId}");
        }

        public void Shutdown()
        {
            _authToken = null;
        }

        // Аутентификация
        public IEnumerator Authenticate(string initData, Action<AuthResponse> onSuccess, Action<string> onError)
        {
            var request = new AuthRequest
            {
                initData = initData
            };

            yield return PostRequest("/auth/telegram", request, 
                (ApiResponse<AuthResponse> response) =>
                {
                    _authToken = response.data.token;
                    PlayerPrefs.SetString("api_token", _authToken);
                    PlayerPrefs.Save();
                    onSuccess?.Invoke(response.data);
                },
                onError,
                useAuth: false
            );
        }

        // Отправка пакета тапов
        public IEnumerator SendTapBatch(List<TapData> taps, Action<TapBatchResponse> onSuccess, Action<string> onError)
        {
            var request = new TapBatchRequest
            {
                taps = taps,
                clientTime = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                sessionId = _sessionId
            };

            yield return PostRequest("/gameplay/tap-batch", request, 
                (ApiResponse<TapBatchResponse> response) =>
                {
                    onSuccess?.Invoke(response.data);
                },
                onError
            );
        }

        // Получение данных игрока
        public IEnumerator GetPlayerData(Action<PlayerData> onSuccess, Action<string> onError)
        {
            yield return GetRequest("/player/me",
                (ApiResponse<PlayerData> response) =>
                {
                    onSuccess?.Invoke(response.data);
                },
                onError
            );
        }

        // Синхронизация состояния
        public IEnumerator SyncGameState(Action<SyncResponse> onSuccess, Action<string> onError)
        {
            var request = new SyncRequest
            {
                lastKnownServerTime = PlayerPrefs.GetString("last_server_time", DateTime.UtcNow.ToString("o")),
                clientTime = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            };

            yield return PostRequest("/gameplay/sync", request,
                (ApiResponse<SyncResponse> response) =>
                {
                    onSuccess?.Invoke(response.data);
                },
                onError
            );
        }

        // Получение оффлайн бонуса
        public IEnumerator ClaimOfflineBonus(Action<OfflineRewards> onSuccess, Action<string> onError)
        {
            yield return PostRequest("/player/claim-offline-bonus", new {},
                (ApiResponse<OfflineBonusResponse> response) =>
                {
                    onSuccess?.Invoke(response.data);
                },
                onError
            );
        }

        // Базовые HTTP методы
        private IEnumerator GetRequest<T>(string endpoint, Action<ApiResponse<T>> onSuccess, Action<string> onError, bool useAuth = true)
        {
            using (UnityWebRequest www = UnityWebRequest.Get(BASE_URL + endpoint))
            {
                if (useAuth && !string.IsNullOrEmpty(_authToken))
                {
                    www.SetRequestHeader("Authorization", $"Bearer {_authToken}");
                }

                yield return www.SendWebRequest();

                yield return HandleResponse(www, onSuccess, onError);
            }
        }

        private IEnumerator PostRequest<TRequest, TResponse>(string endpoint, TRequest data, Action<ApiResponse<TResponse>> onSuccess, Action<string> onError, bool useAuth = true)
        {
            string json = JsonConvert.SerializeObject(data);
            byte[] bodyRaw = System.Text.Encoding.UTF8.GetBytes(json);

            using (UnityWebRequest www = new UnityWebRequest(BASE_URL + endpoint, "POST"))
            {
                www.uploadHandler = new UploadHandlerRaw(bodyRaw);
                www.downloadHandler = new DownloadHandlerBuffer();
                www.SetRequestHeader("Content-Type", "application/json");

                if (useAuth && !string.IsNullOrEmpty(_authToken))
                {
                    www.SetRequestHeader("Authorization", $"Bearer {_authToken}");
                }

                yield return www.SendWebRequest();

                yield return HandleResponse(www, onSuccess, onError);
            }
        }

        private IEnumerator HandleResponse<T>(UnityWebRequest www, Action<ApiResponse<T>> onSuccess, Action<string> onError)
        {
            if (www.result == UnityWebRequest.Result.Success)
            {
                try
                {
                    var response = JsonConvert.DeserializeObject<ApiResponse<T>>(www.downloadHandler.text);

                    if (response.success)
                    {
                        // Сохранить серверное время
                        if (!string.IsNullOrEmpty(response.serverTime))
                        {
                            PlayerPrefs.SetString("last_server_time", response.serverTime);
                        }

                        onSuccess?.Invoke(response);
                    }
                    else
                    {
                        onError?.Invoke(response.error?.message ?? "Unknown error");
                    }
                }
                catch (Exception e)
                {
                    Debug.LogError($"[WattsTapAPI] Parse error: {e.Message}");
                    onError?.Invoke($"Failed to parse response: {e.Message}");
                }
            }
            else
            {
                // Обработка ошибок HTTP
                Debug.LogError($"[WattsTapAPI] Request failed: {www.error}");

                // Попытка получить детали ошибки
                if (!string.IsNullOrEmpty(www.downloadHandler.text))
                {
                    try
                    {
                        var errorResponse = JsonConvert.DeserializeObject<ErrorResponse>(www.downloadHandler.text);
                        onError?.Invoke(errorResponse.error?.message ?? www.error);
                    }
                    catch
                    {
                        onError?.Invoke(www.error);
                    }
                }
                else
                {
                    onError?.Invoke(www.error);
                }
            }

            yield return null;
        }
    }

    // DTO классы
    [Serializable]
    public class ApiResponse<T>
    {
        public bool success;
        public T data;
        public string serverTime;
        public ErrorInfo error;
    }

    [Serializable]
    public class ErrorResponse
    {
        public bool success;
        public ErrorInfo error;
        public string serverTime;
    }

    [Serializable]
    public class ErrorInfo
    {
        public string code;
        public string message;
        public Dictionary<string, object> details;
    }

    [Serializable]
    public class AuthRequest
    {
        public string initData;
    }

    [Serializable]
    public class AuthResponse
    {
        public string token;
        public int expiresIn;
        public PlayerInfo player;
    }

    [Serializable]
    public class PlayerInfo
    {
        public string playerId;
        public string nickname;
        public int level;
        public bool isNewPlayer;
    }

    [Serializable]
    public class TapBatchRequest
    {
        public List<TapData> taps;
        public long clientTime;
        public string sessionId;
    }

    [Serializable]
    public class TapData
    {
        public long clientTimestamp;
        public Vector2Data screenPosition;
    }

    [Serializable]
    public class Vector2Data
    {
        public float x;
        public float y;

        public Vector2Data(Vector2 vec)
        {
            x = vec.x;
            y = vec.y;
        }
    }

    [Serializable]
    public class TapBatchResponse
    {
        public int validTapsCount;
        public int invalidTapsCount;
        public long wattsEarned;
        public long xpEarned;
        public PlayerResources resources;
        public List<TapEffect> effects;
        public LevelUpInfo levelUp;
    }

    [Serializable]
    public class TapEffect
    {
        public string type;
        public Vector2Data position;
        public float value;
        public float multiplier;
    }

    [Serializable]
    public class LevelUpInfo
    {
        public int newLevel;
        public Rewards rewards;
    }

    [Serializable]
    public class Rewards
    {
        public long watts;
        public long xp;
        public string kiloWattTokens;
        public List<InventoryItem> items;
    }

    [Serializable]
    public class SyncRequest
    {
        public string lastKnownServerTime;
        public long clientTime;
    }

    [Serializable]
    public class SyncResponse
    {
        public PlayerResources resources;
        public OfflineRewards offlineRewards;
        public int hitsRecovered;
    }

    [Serializable]
    public class OfflineRewards
    {
        public long wattsEarned;
        public int offlineDuration;
        public float multiplier;
        public int maxDuration;
    }

    [Serializable]
    public class OfflineBonusResponse : OfflineRewards
    {
        public PlayerResources resources;
    }
}
```

##  Интеграция в Tap System

### 2. Модификация TapControllerService для работы с API

```csharp
// Assets/WattsTap/Scripts/Game/Tap/Services/TapControllerService.cs
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using WattsTap.Core;
using WattsTap.Core.API;

namespace WattsTap.Scripts.Game.Tap.Services
{
    public class TapControllerService : ITapControllerService
    {
        private List<TapData> _pendingTaps = new List<TapData>();
        private const int BATCH_SIZE = 10; // Отправляем по 10 тапов
        private const float BATCH_TIMEOUT = 2f; // Или каждые 2 секунды
        private float _timeSinceLastBatch = 0f;

        private IWattsTapAPIService _apiService;
        private IPlayerService _playerService;

        public void Initialize()
        {
            _apiService = ServiceLocator.Get<IWattsTapAPIService>();
            _playerService = ServiceLocator.Get<IPlayerService>();
        }

        public void HandleTap(Vector2 screenPosition)
        {
            var playerData = _playerService.GetPlayerData();

            // Локальная проверка возможности тапа
            if (playerData.resources.currentHits <= 0)
            {
                Debug.Log("[TapController] No hits available");
                return;
            }

            // Добавляем тап в очередь
            _pendingTaps.Add(new TapData
            {
                clientTimestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                screenPosition = new Vector2Data(screenPosition)
            });

            // Оптимистичное обновление UI (будет скорректировано сервером)
            _playerService.UpdateResourcesOptimistic(-1, 0); // -1 hit

            // Отправляем пакет если накопилось достаточно
            if (_pendingTaps.Count >= BATCH_SIZE)
            {
                SendTapBatch();
            }
        }

        public void Update(float deltaTime)
        {
            _timeSinceLastBatch += deltaTime;

            // Отправляем оставшиеся тапы по таймауту
            if (_pendingTaps.Count > 0 && _timeSinceLastBatch >= BATCH_TIMEOUT)
            {
                SendTapBatch();
            }
        }

        private void SendTapBatch()
        {
            if (_pendingTaps.Count == 0) return;

            var tapsToSend = new List<TapData>(_pendingTaps);
            _pendingTaps.Clear();
            _timeSinceLastBatch = 0f;

            // Корутина для отправки
            CoroutineRunner.Instance.StartCoroutine(
                _apiService.SendTapBatch(
                    tapsToSend,
                    onSuccess: (response) => OnTapBatchSuccess(response),
                    onError: (error) => OnTapBatchError(error, tapsToSend)
                )
            );
        }

        private void OnTapBatchSuccess(TapBatchResponse response)
        {
            Debug.Log($"[TapController] Batch processed: {response.validTapsCount} valid, {response.wattsEarned} watts earned");

            // Обновляем ресурсы из серверного ответа
            _playerService.UpdateResourcesFromServer(response.resources);

            // Показываем эффекты
            foreach (var effect in response.effects)
            {
                ShowTapEffect(effect);
            }

            // Проверяем level up
            if (response.levelUp != null)
            {
                OnLevelUp(response.levelUp);
            }
        }

        private void OnTapBatchError(string error, List<TapData> failedTaps)
        {
            Debug.LogError($"[TapController] Batch failed: {error}");

            // В случае ошибки возвращаем тапы обратно или синхронизируем состояние
            CoroutineRunner.Instance.StartCoroutine(
                _apiService.SyncGameState(
                    onSuccess: (syncResponse) =>
                    {
                        _playerService.UpdateResourcesFromServer(syncResponse.resources);
                    },
                    onError: (syncError) =>
                    {
                        Debug.LogError($"[TapController] Sync failed: {syncError}");
                    }
                )
            );
        }

        private void ShowTapEffect(TapEffect effect)
        {
            // Показать визуальный эффект на позиции тапа
            var effectService = ServiceLocator.Get<IVFXService>();

            switch (effect.type)
            {
                case "tap_success":
                    effectService?.PlayTapEffect(
                        new Vector2(effect.position.x, effect.position.y),
                        effect.value
                    );
                    break;
                case "combo":
                    effectService?.PlayComboEffect(effect.multiplier);
                    break;
                case "critical":
                    effectService?.PlayCriticalEffect(
                        new Vector2(effect.position.x, effect.position.y),
                        effect.value
                    );
                    break;
            }
        }

        private void OnLevelUp(LevelUpInfo levelUp)
        {
            Debug.Log($"[TapController] LEVEL UP! New level: {levelUp.newLevel}");

            // Показать Level Up UI
            var uiService = ServiceLocator.Get<IUIService>();
            uiService?.ShowLevelUpPopup(levelUp);
        }
    }
}
```

### 3. CoroutineRunner Helper

```csharp
// Assets/WattsTap/Scripts/Core/Utilities/CoroutineRunner.cs
using UnityEngine;

namespace WattsTap.Core
{
    /// <summary>
    /// Singleton для запуска корутин из не-MonoBehaviour классов
    /// </summary>
    public class CoroutineRunner : MonoBehaviour
    {
        private static CoroutineRunner _instance;

        public static CoroutineRunner Instance
        {
            get
            {
                if (_instance == null)
                {
                    var go = new GameObject("CoroutineRunner");
                    _instance = go.AddComponent<CoroutineRunner>();
                    DontDestroyOnLoad(go);
                }
                return _instance;
            }
        }
    }
}
```

##  Примеры использования

### Пример 1: Аутентификация при запуске

```csharp
// Assets/WattsTap/Scripts/Game/ApplicationEntry.cs
public class ApplicationEntry : MonoBehaviour
{
    private IWattsTapAPIService _apiService;

    private IEnumerator Start()
    {
        // Регистрация сервисов
        ServiceLocator.Register<IWattsTapAPIService>(new WattsTapAPIService());
        ServiceLocator.Register<IPlayerService>(new PlayerService());
        ServiceLocator.Register<ITapControllerService>(new TapControllerService());

        ServiceLocator.Instance.InitializeAll();

        _apiService = ServiceLocator.Get<IWattsTapAPIService>();

        // Получаем initData от Telegram
        string initData = GetTelegramInitData();

        bool authSuccess = false;

        yield return _apiService.Authenticate(
            initData,
            onSuccess: (authResponse) =>
            {
                Debug.Log($"Auth successful! Player: {authResponse.player.nickname}");
                authSuccess = true;

                if (authResponse.player.isNewPlayer)
                {
                    ShowWelcomeScreen();
                }
            },
            onError: (error) =>
            {
                Debug.LogError($"Auth failed: {error}");
                ShowErrorScreen(error);
            }
        );

        if (authSuccess)
        {
            // Загружаем данные игрока
            yield return LoadPlayerData();

            // Проверяем оффлайн награды
            yield return ClaimOfflineRewards();

            // Запускаем игру
            StartGame();
        }
    }

    private IEnumerator LoadPlayerData()
    {
        var playerService = ServiceLocator.Get<IPlayerService>();

        yield return _apiService.GetPlayerData(
            onSuccess: (playerData) =>
            {
                playerService.SetPlayerData(playerData);
                Debug.Log($"Player data loaded: Level {playerData.level}, {playerData.resources.watts} watts");
            },
            onError: (error) =>
            {
                Debug.LogError($"Failed to load player data: {error}");
            }
        );
    }

    private IEnumerator ClaimOfflineRewards()
    {
        yield return _apiService.ClaimOfflineBonus(
            onSuccess: (rewards) =>
            {
                if (rewards.wattsEarned > 0)
                {
                    Debug.Log($"Offline rewards: +{rewards.wattsEarned} watts for {rewards.offlineDuration}s");
                    ShowOfflineRewardsPopup(rewards);
                }
            },
            onError: (error) =>
            {
                // Не критично если не удалось получить оффлайн награды
                Debug.LogWarning($"Could not claim offline bonus: {error}");
            }
        );
    }

    private string GetTelegramInitData()
    {
        // В production получаем от Telegram WebApp
        #if UNITY_WEBGL && !UNITY_EDITOR
            return GetTelegramInitDataFromJS();
        #else
            // В редакторе используем моковые данные для тестирования
            return "query_id=test&user=%7B%22id%22%3A123456789%7D";
        #endif
    }

    [System.Runtime.InteropServices.DllImport("__Internal")]
    private static extern string GetTelegramInitDataFromJS();
}
```

### Пример 2: Обработка тапов в UI

```csharp
// Assets/WattsTap/Scripts/Game/UI/TapArea.cs
using UnityEngine;
using UnityEngine.EventSystems;
using WattsTap.Core;
using WattsTap.Scripts.Game.Tap.Services;

public class TapArea : MonoBehaviour, IPointerDownHandler
{
    private ITapControllerService _tapController;

    private void Start()
    {
        _tapController = ServiceLocator.Get<ITapControllerService>();
    }

    public void OnPointerDown(PointerEventData eventData)
    {
        // Передаём тап в контроллер с позицией на экране
        _tapController.HandleTap(eventData.position);

        // Локальная визуализация (мгновенная)
        PlayLocalTapAnimation(eventData.position);
    }

    private void PlayLocalTapAnimation(Vector2 position)
    {
        // Показываем локальную анимацию сразу для отзывчивости UI
        // Реальные награды придут от сервера
    }
}
```

### Пример 3: Покупка улучшения

```csharp
// Assets/WattsTap/Scripts/Game/UI/UpgradeButton.cs
using UnityEngine;
using UnityEngine.UI;
using WattsTap.Core;
using WattsTap.Core.API;

public class UpgradeButton : MonoBehaviour
{
    [SerializeField] private string upgradeId;
    [SerializeField] private Button button;
    [SerializeField] private Text costText;

    private IWattsTapAPIService _apiService;

    private void Start()
    {
        _apiService = ServiceLocator.Get<IWattsTapAPIService>();
        button.onClick.AddListener(OnPurchaseClick);
    }

    private void OnPurchaseClick()
    {
        button.interactable = false;

        StartCoroutine(_apiService.PurchaseUpgrade(
            upgradeId,
            onSuccess: (response) =>
            {
                Debug.Log($"Upgrade purchased! New level: {response.upgrade.newLevel}");

                // Обновляем ресурсы
                var playerService = ServiceLocator.Get<IPlayerService>();
                playerService.UpdateResourcesFromServer(response.resources);

                // Обновляем UI
                RefreshUI();

                button.interactable = true;
            },
            onError: (error) =>
            {
                Debug.LogError($"Purchase failed: {error}");
                ShowErrorMessage(error);
                button.interactable = true;
            }
        ));
    }
}
```

##  Настройка для разных окружений

### Development / Staging / Production

```csharp
// Assets/WattsTap/Scripts/Core/Config/APIConfig.cs
using UnityEngine;

namespace WattsTap.Core.Config
{
    [CreateAssetMenu(menuName = "WattsTap/API Config")]
    public class APIConfig : ScriptableObject
    {
        public Environment environment = Environment.Production;

        public string GetBaseURL()
        {
            return environment switch
            {
                Environment.Development => "https://api-dev.wattstap.com/v1",
                Environment.Staging => "https://api-staging.wattstap.com/v1",
                Environment.Production => "https://api.wattstap.com/v1",
                _ => "https://api.wattstap.com/v1"
            };
        }
    }

    public enum Environment
    {
        Development,
        Staging,
        Production
    }
}
```

##  Мониторинг и отладка

### Debug Logger для API запросов

```csharp
// Assets/WattsTap/Scripts/Core/API/APILogger.cs
using UnityEngine;

namespace WattsTap.Core.API
{
    public static class APILogger
    {
        private static bool _enableLogging = true;

        public static void LogRequest(string endpoint, object requestData)
        {
            if (!_enableLogging) return;

            Debug.Log($"[API] → {endpoint}\n{JsonUtility.ToJson(requestData, true)}");
        }

        public static void LogResponse(string endpoint, object responseData)
        {
            if (!_enableLogging) return;

            Debug.Log($"[API] ← {endpoint}\n{JsonUtility.ToJson(responseData, true)}");
        }

        public static void LogError(string endpoint, string error)
        {
            Debug.LogError($"[API] ✗ {endpoint}: {error}");
        }
    }
}
```

##  Best Practices

1. **Batching тапов**: Не отправляйте каждый тап отдельно - используйте пакеты по 5-10 тапов
2. **Optimistic Updates**: Обновляйте UI локально сразу, корректируйте по ответу сервера
3. **Error Handling**: Всегда обрабатывайте ошибки и имейте fallback логику
4. **Синхронизация**: При возобновлении приложения вызывайте `/gameplay/sync`
5. **Кэширование токена**: Сохраняйте JWT токен в PlayerPrefs для повторного использования
6. **Rate Limiting**: Учитывайте лимиты запросов в UI (показывайте cooldowns)
7. **Server Time**: Используйте серверное время для критичных проверок

##  Deployment Checklist

- [ ] Переключить API на production URL
- [ ] Отключить debug логирование
- [ ] Настроить обработку ошибок сети
- [ ] Добавить аналитику для API ошибок
- [ ] Настроить retry логику для критичных запросов
- [ ] Проверить CORS настройки для WebGL домена
- [ ] Тестирование на медленном интернете
- [ ] Тестирование offline режима

using UnityEngine;
using UnityEditor;
using WattsTap.Core.API;
using WattsTap.Core;

namespace WattsTap.Editor
{
    /// <summary>
    /// Editor window для управления Mock API сервисом
    /// Позволяет тестировать API функционал без реального сервера
    /// </summary>
    public class MockAPIControlWindow : EditorWindow
    {
        private WattsTapAPIMockService _mockService;
        private Vector2 _scrollPosition;

        // Параметры для тестирования
        private long _wattsToAdd = 1000;
        private long _xpToAdd = 500;
        private int _levelToSet = 1;
        private float _errorChance = 0.0f;
        private bool _simulateNetworkDelay = true;
        private float _minDelay = 0.1f;
        private float _maxDelay = 0.5f;

        [MenuItem("WattsTap/Mock API Control Panel")]
        public static void ShowWindow()
        {
            var window = GetWindow<MockAPIControlWindow>("Mock API Control");
            window.minSize = new Vector2(400, 600);
        }

        private void OnEnable()
        {
            RefreshMockService();
        }

        private void RefreshMockService()
        {
            if (Application.isPlaying)
            {
                _mockService = ServiceLocator.Get<IWattsTapAPIService>() as WattsTapAPIMockService;
            }
        }

        private void OnGUI()
        {
            _scrollPosition = EditorGUILayout.BeginScrollView(_scrollPosition);

            DrawHeader();
            EditorGUILayout.Space(10);

            DrawConnectionStatus();
            EditorGUILayout.Space(10);

            if (_mockService != null)
            {
                DrawPlayerDataSection();
                EditorGUILayout.Space(10);

                DrawResourcesSection();
                EditorGUILayout.Space(10);

                DrawSimulationSettings();
                EditorGUILayout.Space(10);

                DrawQuickActions();
            }
            else
            {
                DrawNotPlayingMessage();
            }

            EditorGUILayout.EndScrollView();
        }

        private void DrawHeader()
        {
            GUILayout.Label("Mock API Control Panel", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox(
                "Эта панель позволяет управлять Mock API сервисом для тестирования игры в редакторе без реального бэкенда.",
                MessageType.Info
            );
        }

        private void DrawConnectionStatus()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Status", EditorStyles.boldLabel);

            if (Application.isPlaying)
            {
                if (_mockService != null)
                {
                    EditorGUILayout.LabelField("Service Status:", "✓ Mock API Active");
                    GUI.color = Color.green;
                    EditorGUILayout.LabelField("Mode:", "MOCK (Editor Testing)");
                    GUI.color = Color.white;
                }
                else
                {
                    EditorGUILayout.LabelField("Service Status:", "⚠ Real API Active");
                    GUI.color = Color.yellow;
                    EditorGUILayout.LabelField("Mode:", "PRODUCTION");
                    GUI.color = Color.white;
                    EditorGUILayout.HelpBox("Mock service not found. Are you using WattsTapAPIMockService?", MessageType.Warning);
                }

                if (GUILayout.Button("Refresh Service Reference"))
                {
                    RefreshMockService();
                }
            }
            else
            {
                EditorGUILayout.LabelField("Service Status:", "Not Running");
                GUI.color = Color.gray;
                EditorGUILayout.LabelField("Play mode required");
                GUI.color = Color.white;
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawPlayerDataSection()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Player Data", EditorStyles.boldLabel);

            var playerData = _mockService.GetCurrentMockData();
            if (playerData != null)
            {
                EditorGUI.indentLevel++;

                EditorGUILayout.LabelField("Player ID:", playerData.playerId);
                EditorGUILayout.LabelField("Nickname:", playerData.nickname);
                EditorGUILayout.LabelField("Level:", playerData.level.ToString());

                EditorGUILayout.Space(5);
                EditorGUILayout.LabelField("Resources:", EditorStyles.boldLabel);
                EditorGUI.indentLevel++;
                EditorGUILayout.LabelField("Watts:", playerData.resources.watts.ToString("N0"));
                EditorGUILayout.LabelField("Current XP:", playerData.resources.currentXP.ToString("N0"));
                EditorGUILayout.LabelField("XP to Next Level:", playerData.resources.xpToNextLevel.ToString("N0"));
                EditorGUILayout.LabelField("Current Hits:", $"{playerData.resources.currentHits} / {playerData.resources.maxHits}");
                EditorGUILayout.LabelField("Energy:", $"{playerData.resources.currentEnergy} / {playerData.resources.maxEnergy}");
                EditorGUI.indentLevel--;

                EditorGUILayout.Space(5);
                EditorGUILayout.LabelField("Statistics:", EditorStyles.boldLabel);
                EditorGUI.indentLevel++;
                EditorGUILayout.LabelField("Total Taps:", playerData.stats.totalTaps.ToString("N0"));
                EditorGUILayout.LabelField("Income per Tap:", playerData.stats.incomePerTap.ToString("N0"));
                EditorGUILayout.LabelField("Income per Hour:", playerData.stats.incomePerHour.ToString("N0"));
                EditorGUI.indentLevel--;

                EditorGUI.indentLevel--;
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawResourcesSection()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Modify Resources", EditorStyles.boldLabel);

            // Add Watts
            EditorGUILayout.BeginHorizontal();
            _wattsToAdd = EditorGUILayout.LongField("Watts to Add:", _wattsToAdd);
            if (GUILayout.Button("Add Watts", GUILayout.Width(100)))
            {
                _mockService.AddWatts(_wattsToAdd);
            }
            EditorGUILayout.EndHorizontal();

            // Add XP
            EditorGUILayout.BeginHorizontal();
            _xpToAdd = EditorGUILayout.LongField("XP to Add:", _xpToAdd);
            if (GUILayout.Button("Add XP", GUILayout.Width(100)))
            {
                _mockService.AddXP(_xpToAdd);
            }
            EditorGUILayout.EndHorizontal();

            // Set Level
            EditorGUILayout.BeginHorizontal();
            _levelToSet = EditorGUILayout.IntField("Set Level:", _levelToSet);
            if (GUILayout.Button("Set Level", GUILayout.Width(100)))
            {
                _mockService.SetLevel(_levelToSet);
            }
            EditorGUILayout.EndHorizontal();

            EditorGUILayout.Space(5);

            // Restore Hits
            if (GUILayout.Button("Restore Hits to Max"))
            {
                _mockService.RestoreHits();
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawSimulationSettings()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Simulation Settings", EditorStyles.boldLabel);

            // Network Delay
            _simulateNetworkDelay = EditorGUILayout.Toggle("Simulate Network Delay:", _simulateNetworkDelay);
            if (_simulateNetworkDelay)
            {
                EditorGUI.indentLevel++;
                _minDelay = EditorGUILayout.Slider("Min Delay (s):", _minDelay, 0f, 2f);
                _maxDelay = EditorGUILayout.Slider("Max Delay (s):", _maxDelay, 0f, 2f);
                EditorGUI.indentLevel--;

                // Применяем значения
                _mockService.simulateNetworkDelay = _simulateNetworkDelay;
                _mockService.minDelay = _minDelay;
                _mockService.maxDelay = Mathf.Max(_maxDelay, _minDelay);
            }

            EditorGUILayout.Space(5);

            // Error Simulation
            _errorChance = EditorGUILayout.Slider("Error Chance (%):", _errorChance * 100f, 0f, 100f) / 100f;
            if (GUILayout.Button("Apply Error Chance"))
            {
                _mockService.SetErrorChance(_errorChance);
            }

            EditorGUILayout.HelpBox(
                "Error Chance симулирует случайные ошибки API (например, сетевые проблемы). " +
                "Полезно для тестирования error handling в клиенте.",
                MessageType.Info
            );

            EditorGUILayout.EndVertical();
        }

        private void DrawQuickActions()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Quick Actions", EditorStyles.boldLabel);

            EditorGUILayout.BeginHorizontal();

            if (GUILayout.Button(" Add 10K Watts"))
            {
                _mockService.AddWatts(10000);
            }

            if (GUILayout.Button("⚡ Add 1K XP"))
            {
                _mockService.AddXP(1000);
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.BeginHorizontal();

            if (GUILayout.Button(" Reset Player Data"))
            {
                if (EditorUtility.DisplayDialog("Reset Player Data", 
                    "Are you sure you want to reset all player data to default?", "Yes", "Cancel"))
                {
                    _mockService.ResetPlayerData();
                }
            }

            if (GUILayout.Button("❤️ Restore Hits"))
            {
                _mockService.RestoreHits();
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.BeginHorizontal();

            if (GUILayout.Button(" Level Up"))
            {
                var currentData = _mockService.GetCurrentMockData();
                _mockService.SetLevel(currentData.level + 1);
            }

            if (GUILayout.Button(" Add Million Watts"))
            {
                _mockService.AddWatts(1000000);
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.EndVertical();
        }

        private void DrawNotPlayingMessage()
        {
            EditorGUILayout.HelpBox(
                "Enter Play Mode to use Mock API Control Panel.\n\n" +
                "Make sure you register WattsTapAPIMockService instead of WattsTapAPIService in your ApplicationEntry.",
                MessageType.Warning
            );

            EditorGUILayout.Space(10);

            if (GUILayout.Button("Enter Play Mode"))
            {
                EditorApplication.isPlaying = true;
            }
        }

        private void OnInspectorUpdate()
        {
            // Обновляем окно каждые 0.5 секунды когда в play mode
            if (Application.isPlaying)
            {
                Repaint();
            }
        }
    }
}

using UnityEngine;

namespace WattsTap.Core.API
{
    /// <summary>
    /// ScriptableObject конфигурация для Mock API
    /// Позволяет настраивать поведение мока через Inspector
    /// </summary>
    [CreateAssetMenu(fileName = "MockAPIConfig", menuName = "WattsTap/API/Mock API Config")]
    public class MockAPIConfig : ScriptableObject
    {
        [Header("Network Simulation")]
        [Tooltip("Симулировать задержку сети")]
        public bool simulateNetworkDelay = true;

        [Tooltip("Минимальная задержка в секундах")]
        [Range(0f, 2f)]
        public float minDelay = 0.1f;

        [Tooltip("Максимальная задержка в секундах")]
        [Range(0f, 5f)]
        public float maxDelay = 0.5f;

        [Header("Error Simulation")]
        [Tooltip("Вероятность ошибки (0 = никогда, 1 = всегда)")]
        [Range(0f, 1f)]
        public float errorChance = 0.0f;

        [Tooltip("Типы ошибок для симуляции")]
        public ErrorType[] possibleErrors = new ErrorType[]
        {
            ErrorType.NetworkTimeout,
            ErrorType.ServerError,
            ErrorType.RateLimitExceeded
        };

        [Header("Mock Player Data")]
        [Tooltip("Начальное количество Watts")]
        public long startingWatts = 10000;

        [Tooltip("Начальный уровень игрока")]
        public int startingLevel = 5;

        [Tooltip("Начальное количество ударов")]
        public int startingHits = 18;

        [Tooltip("Максимальное количество ударов")]
        public int maxHits = 20;

        [Tooltip("Доход за тап")]
        public long incomePerTap = 50;

        [Tooltip("Пассивный доход в час")]
        public long incomePerHour = 1000;

        [Header("Offline Simulation")]
        [Tooltip("Симулировать время оффлайн (в часах)")]
        [Range(0f, 24f)]
        public float offlineHours = 1f;

        [Header("Gameplay Tweaks")]
        [Tooltip("Множитель опыта (для быстрого тестирования level up)")]
        [Range(1f, 10f)]
        public float xpMultiplier = 1f;

        [Tooltip("Автоматически давать level up при достижении XP")]
        public bool autoLevelUp = true;

        [Tooltip("Бесконечные удары (не тратятся при тапах)")]
        public bool infiniteHits = false;

        [Header("Logging")]
        [Tooltip("Выводить подробные логи в консоль")]
        public bool verboseLogging = true;

        [Tooltip("Показывать время ответа в логах")]
        public bool logResponseTime = true;

        public enum ErrorType
        {
            NetworkTimeout,
            ServerError,
            InvalidToken,
            RateLimitExceeded,
            InsufficientResources
        }

        public string GetRandomErrorMessage()
        {
            if (possibleErrors.Length == 0)
                return "Unknown error";

            var errorType = possibleErrors[Random.Range(0, possibleErrors.Length)];

            return errorType switch
            {
                ErrorType.NetworkTimeout => "Network timeout. Please check your connection.",
                ErrorType.ServerError => "Internal server error. Please try again later.",
                ErrorType.InvalidToken => "Invalid or expired authentication token.",
                ErrorType.RateLimitExceeded => "Rate limit exceeded. Please slow down.",
                ErrorType.InsufficientResources => "Insufficient resources to complete this action.",
                _ => "Unknown error occurred."
            };
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using WattsTap.Game.Player;

namespace WattsTap.Core.API
{
    /// <summary>
    /// Mock-реализация API сервиса для тестирования в редакторе
    /// Симулирует серверные ответы без реального бэкенда
    /// </summary>
    public class WattsTapAPIMockService : IWattsTapAPIService
    {
        private string _authToken;
        private string _sessionId;
        private PlayerData _mockPlayerData;
        private int _tapCounter = 0;
        private DateTime _lastLogoutTime;
        private MockAPIConfig _config;

        // Публичные поля для контроля из Editor Window
        public bool simulateNetworkDelay = true;
        public float minDelay = 0.1f;
        public float maxDelay = 0.5f;
        public float errorChance = 0.0f;

        public int InitializationOrder => 5;

        public WattsTapAPIMockService(MockAPIConfig config = null)
        {
            _config = config;
            if (_config != null)
            {
                simulateNetworkDelay = _config.simulateNetworkDelay;
                minDelay = _config.minDelay;
                maxDelay = _config.maxDelay;
                errorChance = _config.errorChance;
            }
        }

        public void Initialize()
        {
            _sessionId = Guid.NewGuid().ToString();

            // Устанавливаем время последнего выхода из конфига
            float offlineHours = _config != null ? _config.offlineHours : 1f;
            _lastLogoutTime = DateTime.UtcNow.AddHours(-offlineHours);

            InitializeMockPlayerData();

            LogInfo($"Service initialized with session: {_sessionId}");
            LogInfo($"Network delay: {simulateNetworkDelay}, Error chance: {errorChance * 100}%");
        }

        public void Shutdown()
        {
            _authToken = null;
            _lastLogoutTime = DateTime.UtcNow;
        }

        private void InitializeMockPlayerData()
        {
            long startingWatts = _config != null ? _config.startingWatts : 10000;
            int startingLevel = _config != null ? _config.startingLevel : 5;
            int startingHits = _config != null ? _config.startingHits : 18;
            int maxHits = _config != null ? _config.maxHits : 20;
            long incomePerTap = _config != null ? _config.incomePerTap : 50;
            long incomePerHour = _config != null ? _config.incomePerHour : 1000;

            _mockPlayerData = new PlayerData
            {
                playerId = Guid.NewGuid().ToString(),
                nickname = "MockPlayer",
                level = startingLevel,
                avatarUrl = "https://via.placeholder.com/150",
                telegramUserId = 123456789,
                tonWalletAddress = "",
                resources = new PlayerResources
                {
                    watts = startingWatts,
                    currentEnergy = 80,
                    maxEnergy = 100,
                    currentXP = 2500,
                    xpToNextLevel = CalculateXPForNextLevel(startingLevel),
                    kiloWattTokens = 0,
                    currentHits = startingHits,
                    maxHits = maxHits
                },
                stats = new PlayerStats
                {
                    totalTaps = 500,
                    totalPlayTimeSeconds = 3600,
                    incomePerHour = incomePerHour,
                    incomePerTap = incomePerTap,
                    friendsCount = 3,
                    upgradesPurchased = 5,
                    chestsOpened = 2,
                    tournamentRank = 0,
                    bestTournamentRank = 0,
                    lastLoginTime = DateTime.UtcNow
                },
                inventory = new InventoryData(),
                dailyLoginStreak = 3,
                lastDailyBonusDate = DateTime.UtcNow.AddDays(-1),
                createdAt = DateTime.UtcNow.AddDays(-30),
                updatedAt = DateTime.UtcNow
            };
        }

        // Аутентификация
        public IEnumerator Authenticate(string initData, Action<AuthResponse> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("Authentication", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            _authToken = $"mock_token_{Guid.NewGuid().ToString().Substring(0, 8)}";

            var response = new AuthResponse
            {
                token = _authToken,
                expiresIn = 86400,
                player = new PlayerInfo
                {
                    playerId = _mockPlayerData.playerId,
                    nickname = _mockPlayerData.nickname,
                    level = _mockPlayerData.level,
                    isNewPlayer = false
                }
            };

            LogSuccess("Authenticate", $"Authenticated as {response.player.nickname}", startTime);
            onSuccess?.Invoke(response);
        }

        // Отправка пакета тапов
        public IEnumerator SendTapBatch(List<TapData> taps, Action<TapBatchResponse> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("SendTapBatch", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            int validTaps = taps.Count;
            int invalidTaps = 0;

            // Проверяем доступность ударов (если не infinite mode)
            bool infiniteHits = _config != null && _config.infiniteHits;
            if (!infiniteHits && _mockPlayerData.resources.currentHits < validTaps)
            {
                validTaps = _mockPlayerData.resources.currentHits;
                invalidTaps = taps.Count - validTaps;
            }

            // Рассчитываем награды
            long wattsPerTap = _mockPlayerData.stats.incomePerTap;
            float xpMultiplier = _config != null ? _config.xpMultiplier : 1f;
            long xpPerTap = (long)(5 * xpMultiplier);
            long totalWatts = wattsPerTap * validTaps;
            long totalXP = xpPerTap * validTaps;

            // Обновляем ресурсы
            if (!infiniteHits)
            {
                _mockPlayerData.resources.currentHits -= validTaps;
            }
            _mockPlayerData.resources.watts += totalWatts;
            _mockPlayerData.resources.currentXP += totalXP;
            _mockPlayerData.stats.totalTaps += validTaps;
            _tapCounter += validTaps;

            // Проверяем level up
            LevelUpInfo levelUp = null;
            bool autoLevelUp = _config == null || _config.autoLevelUp;

            if (autoLevelUp && _mockPlayerData.resources.currentXP >= _mockPlayerData.resources.xpToNextLevel)
            {
                _mockPlayerData.level++;
                _mockPlayerData.resources.currentXP -= _mockPlayerData.resources.xpToNextLevel;
                _mockPlayerData.resources.xpToNextLevel = CalculateXPForNextLevel(_mockPlayerData.level);

                levelUp = new LevelUpInfo
                {
                    newLevel = _mockPlayerData.level,
                    rewards = new Rewards
                    {
                        watts = 1000,
                        xp = 0,
                        kiloWattTokens = null,
                        items = new List<InventoryItem>()
                    }
                };

                LogInfo($" LEVEL UP! New level: {_mockPlayerData.level}");
            }

            // Создаём эффекты
            var effects = new List<TapEffect>();
            for (int i = 0; i < Mathf.Min(validTaps, taps.Count); i++)
            {
                effects.Add(new TapEffect
                {
                    type = "tap_success",
                    position = taps[i].screenPosition,
                    value = wattsPerTap,
                    multiplier = 1.0f
                });
            }

            // Комбо каждые 5 тапов
            if (_tapCounter % 5 == 0 && validTaps > 0)
            {
                effects.Add(new TapEffect
                {
                    type = "combo",
                    position = taps[0].screenPosition,
                    value = 0,
                    multiplier = 1.2f
                });
            }

            var response = new TapBatchResponse
            {
                validTapsCount = validTaps,
                invalidTapsCount = invalidTaps,
                wattsEarned = totalWatts,
                xpEarned = totalXP,
                resources = CloneResources(_mockPlayerData.resources),
                effects = effects,
                levelUp = levelUp
            };

            LogSuccess("SendTapBatch", $"{validTaps} taps, +{totalWatts} watts, +{totalXP} XP", startTime);
            onSuccess?.Invoke(response);
        }

        // Получение данных игрока
        public IEnumerator GetPlayerData(Action<PlayerData> onSuccess, Action<string> onError)
        {
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                onError?.Invoke("Mock error: Failed to fetch player data");
                yield break;
            }

            _mockPlayerData.updatedAt = DateTime.UtcNow;

            Debug.Log($"[MockAPI] ✓ Player data fetched: Level {_mockPlayerData.level}, {_mockPlayerData.resources.watts} watts");
            onSuccess?.Invoke(ClonePlayerData(_mockPlayerData));
        }

        // Синхронизация состояния
        public IEnumerator SyncGameState(Action<SyncResponse> onSuccess, Action<string> onError)
        {
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                onError?.Invoke("Mock error: Sync failed");
                yield break;
            }

            // Восстанавливаем удары
            int hitsRecovered = Mathf.Min(
                _mockPlayerData.resources.maxHits - _mockPlayerData.resources.currentHits,
                5 // Восстанавливаем до 5 ударов
            );
            _mockPlayerData.resources.currentHits += hitsRecovered;

            var response = new SyncResponse
            {
                resources = CloneResources(_mockPlayerData.resources),
                offlineRewards = null,
                hitsRecovered = hitsRecovered
            };

            Debug.Log($"[MockAPI] ✓ Game state synced, recovered {hitsRecovered} hits");
            onSuccess?.Invoke(response);
        }

        // Получение оффлайн бонуса
        public IEnumerator ClaimOfflineBonus(Action<OfflineRewards> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("ClaimOfflineBonus", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            var now = DateTime.UtcNow;
            var offlineDuration = (int)(now - _lastLogoutTime).TotalSeconds;
            var maxDuration = 4 * 3600; // 4 часа
            offlineDuration = Mathf.Min(offlineDuration, maxDuration);

            var incomePerHour = _mockPlayerData.stats.incomePerHour;
            var wattsEarned = (long)(incomePerHour * (offlineDuration / 3600f) * 1.5f); // 1.5x множитель

            _mockPlayerData.resources.watts += wattsEarned;
            _lastLogoutTime = now;

            var rewards = new OfflineRewards
            {
                wattsEarned = wattsEarned,
                offlineDuration = offlineDuration,
                multiplier = 1.5f,
                maxDuration = maxDuration
            };

            LogSuccess("ClaimOfflineBonus", $"+{wattsEarned} watts for {offlineDuration}s offline", startTime);
            onSuccess?.Invoke(rewards);
        }

        // Вспомогательные методы
        private IEnumerator SimulateNetworkDelay()
        {
            if (!simulateNetworkDelay)
                yield break;

            float delay = UnityEngine.Random.Range(minDelay, maxDelay);
            yield return new WaitForSeconds(delay);
        }

        private bool ShouldSimulateError()
        {
            return UnityEngine.Random.value < errorChance;
        }

        private string GetErrorMessage()
        {
            if (_config != null)
                return _config.GetRandomErrorMessage();

            return "Mock error: Request failed";
        }

        private long CalculateXPForNextLevel(int level)
        {
            return 1000 * level + 500 * (level - 1);
        }

        private PlayerData ClonePlayerData(PlayerData original)
        {
            // Простое клонирование через JSON (для мока достаточно)
            string json = JsonUtility.ToJson(original);
            return JsonUtility.FromJson<PlayerData>(json);
        }

        private PlayerResources CloneResources(PlayerResources original)
        {
            return new PlayerResources
            {
                watts = original.watts,
                currentEnergy = original.currentEnergy,
                maxEnergy = original.maxEnergy,
                currentXP = original.currentXP,
                xpToNextLevel = original.xpToNextLevel,
                kiloWattTokens = original.kiloWattTokens,
                currentHits = original.currentHits,
                maxHits = original.maxHits
            };
        }

        // Публичные методы для управления моком из редактора
        public void ResetPlayerData()
        {
            InitializeMockPlayerData();
            Debug.Log("[MockAPI] Player data reset");
        }

        public void AddWatts(long amount)
        {
            _mockPlayerData.resources.watts += amount;
            Debug.Log($"[MockAPI] Added {amount} watts. New balance: {_mockPlayerData.resources.watts}");
        }

        public void AddXP(long amount)
        {
            _mockPlayerData.resources.currentXP += amount;
            Debug.Log($"[MockAPI] Added {amount} XP. Current XP: {_mockPlayerData.resources.currentXP}");
        }

        public void SetLevel(int level)
        {
            _mockPlayerData.level = level;
            _mockPlayerData.resources.xpToNextLevel = CalculateXPForNextLevel(level);
            Debug.Log($"[MockAPI] Set level to {level}");
        }

        public void RestoreHits()
        {
            _mockPlayerData.resources.currentHits = _mockPlayerData.resources.maxHits;
            Debug.Log($"[MockAPI] Hits restored to {_mockPlayerData.resources.maxHits}");
        }

        public void SetErrorChance(float chance)
        {
            errorChance = Mathf.Clamp01(chance);
            Debug.Log($"[MockAPI] Error chance set to {errorChance * 100}%");
        }

        public PlayerData GetCurrentMockData()
        {
            return _mockPlayerData;
        }

        // Logging helpers
        private void LogInfo(string message)
        {
            if (_config == null || _config.verboseLogging)
            {
                Debug.Log($"[MockAPI] {message}");
            }
        }

        private void LogSuccess(string method, string message, float startTime)
        {
            if (_config == null || _config.verboseLogging)
            {
                string timeInfo = "";
                if (_config != null && _config.logResponseTime)
                {
                    float duration = (Time.realtimeSinceStartup - startTime) * 1000f;
                    timeInfo = $" ({duration:F0}ms)";
                }
                Debug.Log($"[MockAPI] ✓ {method}: {message}{timeInfo}");
            }
        }

        private void LogError(string method, string error)
        {
            Debug.LogError($"[MockAPI] ✗ {method}: {error}");
        }
    }
}

using UnityEngine;
using UnityEditor;
using WattsTap.Game.API;
using WattsTap.Core;

namespace WattsTap.Scripts.Game.API.Editor
{
    /// <summary>
    /// Editor window для управления Mock API сервисом
    /// Позволяет тестировать API функционал без реального сервера
    /// </summary>
    public class MockAPIControlWindow : EditorWindow
    {
        private WattsTapAPIMockService _mockService;
        private Vector2 _scrollPosition;

        // Параметры для тестирования
        private long _wattsToAdd = 1000;
        private long _xpToAdd = 500;
        private int _levelToSet = 1;
        private float _errorChance;
        private bool _simulateNetworkDelay = true;
        private float _minDelay = 0.1f;
        private float _maxDelay = 0.5f;

        [MenuItem("WattsTap/Mock API Control Panel")]
        public static void ShowWindow()
        {
            var window = GetWindow<MockAPIControlWindow>("Mock API Control");
            window.minSize = new Vector2(400, 600);
        }

        private void OnEnable()
        {
            RefreshMockService();
        }

        private void RefreshMockService()
        {
            if (Application.isPlaying)
            {
                _mockService = ServiceLocator.Get<IWattsTapAPIService>() as WattsTapAPIMockService;
            }
        }

        private void OnGUI()
        {
            _scrollPosition = EditorGUILayout.BeginScrollView(_scrollPosition);

            DrawHeader();
            EditorGUILayout.Space(10);

            DrawConnectionStatus();
            EditorGUILayout.Space(10);

            if (_mockService != null)
            {
                DrawPlayerDataSection();
                EditorGUILayout.Space(10);

                DrawResourcesSection();
                EditorGUILayout.Space(10);

                DrawSimulationSettings();
                EditorGUILayout.Space(10);

                DrawQuickActions();
            }
            else
            {
                DrawNotPlayingMessage();
            }

            EditorGUILayout.EndScrollView();
        }

        private void DrawHeader()
        {
            GUILayout.Label("Mock API Control Panel", EditorStyles.boldLabel);
            EditorGUILayout.HelpBox(
                "Эта панель позволяет управлять Mock API сервисом для тестирования игры в редакторе без реального бэкенда.",
                MessageType.Info
            );
        }

        private void DrawConnectionStatus()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Status", EditorStyles.boldLabel);

            if (Application.isPlaying)
            {
                if (_mockService != null)
                {
                    EditorGUILayout.LabelField("Service Status:", "✓ Mock API Active");
                    GUI.color = Color.green;
                    EditorGUILayout.LabelField("Mode:", "MOCK (Editor Testing)");
                    GUI.color = Color.white;
                }
                else
                {
                    EditorGUILayout.LabelField("Service Status:", "⚠ Real API Active");
                    GUI.color = Color.yellow;
                    EditorGUILayout.LabelField("Mode:", "PRODUCTION");
                    GUI.color = Color.white;
                    EditorGUILayout.HelpBox("Mock service not found. Are you using WattsTapAPIMockService?", MessageType.Warning);
                }

                if (GUILayout.Button("Refresh Service Reference"))
                {
                    RefreshMockService();
                }
            }
            else
            {
                EditorGUILayout.LabelField("Service Status:", "Not Running");
                GUI.color = Color.gray;
                EditorGUILayout.LabelField("Play mode required");
                GUI.color = Color.white;
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawPlayerDataSection()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Player Data", EditorStyles.boldLabel);

            var playerData = _mockService.GetCurrentMockData();
            if (playerData != null)
            {
                EditorGUI.indentLevel++;

                EditorGUILayout.LabelField("Player ID:", playerData.playerId);
                EditorGUILayout.LabelField("Nickname:", playerData.nickname);
                EditorGUILayout.LabelField("Level:", playerData.level.ToString());

                EditorGUILayout.Space(5);
                EditorGUILayout.LabelField("Resources:", EditorStyles.boldLabel);
                EditorGUI.indentLevel++;
                EditorGUILayout.LabelField("Watts:", playerData.resources.watts.ToString("N0"));
                EditorGUILayout.LabelField("Current XP:", playerData.resources.currentXP.ToString("N0"));
                EditorGUILayout.LabelField("XP to Next Level:", playerData.resources.xpToNextLevel.ToString("N0"));
                EditorGUILayout.LabelField("Current Hits:", $"{playerData.resources.currentHits} / {playerData.resources.maxHits}");
                EditorGUILayout.LabelField("Energy:", $"{playerData.resources.currentEnergy} / {playerData.resources.maxEnergy}");
                EditorGUI.indentLevel--;

                EditorGUILayout.Space(5);
                EditorGUILayout.LabelField("Statistics:", EditorStyles.boldLabel);
                EditorGUI.indentLevel++;
                EditorGUILayout.LabelField("Total Taps:", playerData.stats.totalTaps.ToString("N0"));
                EditorGUILayout.LabelField("Income per Tap:", playerData.stats.incomePerTap.ToString("N0"));
                EditorGUILayout.LabelField("Income per Hour:", playerData.stats.incomePerHour.ToString("N0"));
                EditorGUI.indentLevel--;

                EditorGUI.indentLevel--;
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawResourcesSection()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Modify Resources", EditorStyles.boldLabel);

            // Add Watts
            EditorGUILayout.BeginHorizontal();
            _wattsToAdd = EditorGUILayout.LongField("Watts to Add:", _wattsToAdd);
            if (GUILayout.Button("Add Watts", GUILayout.Width(100)))
            {
                _mockService.AddWatts(_wattsToAdd);
            }
            EditorGUILayout.EndHorizontal();

            // Add XP
            EditorGUILayout.BeginHorizontal();
            _xpToAdd = EditorGUILayout.LongField("XP to Add:", _xpToAdd);
            if (GUILayout.Button("Add XP", GUILayout.Width(100)))
            {
                _mockService.AddXp(_xpToAdd);
            }
            EditorGUILayout.EndHorizontal();

            // Set Level
            EditorGUILayout.BeginHorizontal();
            _levelToSet = EditorGUILayout.IntField("Set Level:", _levelToSet);
            if (GUILayout.Button("Set Level", GUILayout.Width(100)))
            {
                _mockService.SetLevel(_levelToSet);
            }
            EditorGUILayout.EndHorizontal();

            EditorGUILayout.Space(5);

            // Restore Hits
            if (GUILayout.Button("Restore Hits to Max"))
            {
                _mockService.RestoreHits();
            }

            EditorGUILayout.EndVertical();
        }

        private void DrawSimulationSettings()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Simulation Settings", EditorStyles.boldLabel);

            // Network Delay
            _simulateNetworkDelay = EditorGUILayout.Toggle("Simulate Network Delay:", _simulateNetworkDelay);
            if (_simulateNetworkDelay)
            {
                EditorGUI.indentLevel++;
                _minDelay = EditorGUILayout.Slider("Min Delay (s):", _minDelay, 0f, 2f);
                _maxDelay = EditorGUILayout.Slider("Max Delay (s):", _maxDelay, 0f, 2f);
                EditorGUI.indentLevel--;

                // Применяем значения
                _mockService.simulateNetworkDelay = _simulateNetworkDelay;
                _mockService.minDelay = _minDelay;
                _mockService.maxDelay = Mathf.Max(_maxDelay, _minDelay);
            }

            EditorGUILayout.Space(5);

            // Error Simulation
            _errorChance = EditorGUILayout.Slider("Error Chance (%):", _errorChance * 100f, 0f, 100f) / 100f;
            if (GUILayout.Button("Apply Error Chance"))
            {
                _mockService.SetErrorChance(_errorChance);
            }

            EditorGUILayout.HelpBox(
                "Error Chance симулирует случайные ошибки API (например, сетевые проблемы). " +
                "Полезно для тестирования error handling в клиенте.",
                MessageType.Info
            );

            EditorGUILayout.EndVertical();
        }

        private void DrawQuickActions()
        {
            EditorGUILayout.BeginVertical(EditorStyles.helpBox);
            GUILayout.Label("Quick Actions", EditorStyles.boldLabel);

            EditorGUILayout.BeginHorizontal();

            if (GUILayout.Button(" Add 10K Watts"))
            {
                _mockService.AddWatts(10000);
            }

            if (GUILayout.Button("⚡ Add 1K XP"))
            {
                _mockService.AddXp(1000);
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.BeginHorizontal();

            if (GUILayout.Button(" Reset Player Data"))
            {
                if (EditorUtility.DisplayDialog("Reset Player Data", 
                    "Are you sure you want to reset all player data to default?", "Yes", "Cancel"))
                {
                    _mockService.ResetPlayerData();
                }
            }

            if (GUILayout.Button("❤️ Restore Hits"))
            {
                _mockService.RestoreHits();
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.BeginHorizontal();

            if (GUILayout.Button(" Level Up"))
            {
                var currentData = _mockService.GetCurrentMockData();
                _mockService.SetLevel(currentData.level + 1);
            }

            if (GUILayout.Button(" Add Million Watts"))
            {
                _mockService.AddWatts(1000000);
            }

            EditorGUILayout.EndHorizontal();

            EditorGUILayout.EndVertical();
        }

        private void DrawNotPlayingMessage()
        {
            EditorGUILayout.HelpBox(
                "Enter Play Mode to use Mock API Control Panel.\n\n" +
                "Make sure you register WattsTapAPIMockService instead of WattsTapAPIService in your ApplicationEntry.",
                MessageType.Warning
            );

            EditorGUILayout.Space(10);

            if (GUILayout.Button("Enter Play Mode"))
            {
                EditorApplication.isPlaying = true;
            }
        }

        private void OnInspectorUpdate()
        {
            // Обновляем окно каждые 0.5 секунды когда в play mode
            if (Application.isPlaying)
            {
                Repaint();
            }
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using WattsTap.Core;
using WattsTap.Game.Player;

namespace WattsTap.Game.API
{
    /// <summary>
    /// Интерфейс API сервиса для WattsTap
    /// Определяет контракт для работы с бэкендом (реальным или mock)
    /// </summary>
    public interface IWattsTapAPIService : IService
    {
        /// <summary>
        /// Аутентификация через Telegram WebApp
        /// </summary>
        /// <param name="initData">initDataRaw от Telegram WebApp SDK</param>
        /// <param name="onSuccess">Callback при успешной аутентификации</param>
        /// <param name="onError">Callback при ошибке</param>
        IEnumerator Authenticate(string initData, Action<AuthResponse> onSuccess, Action<string> onError);

        /// <summary>
        /// Отправка пакета тапов на сервер
        /// </summary>
        /// <param name="taps">Список тапов для обработки</param>
        /// <param name="onSuccess">Callback с результатом обработки</param>
        /// <param name="onError">Callback при ошибке</param>
        IEnumerator SendTapBatch(List<TapData> taps, Action<TapBatchResponse> onSuccess, Action<string> onError);

        /// <summary>
        /// Получение полных данных игрока
        /// </summary>
        /// <param name="onSuccess">Callback с данными игрока</param>
        /// <param name="onError">Callback при ошибке</param>
        IEnumerator GetPlayerData(Action<PlayerData> onSuccess, Action<string> onError);

        /// <summary>
        /// Синхронизация состояния игры (при переподключении)
        /// </summary>
        /// <param name="onSuccess">Callback с обновленным состоянием</param>
        /// <param name="onError">Callback при ошибке</param>
        IEnumerator SyncGameState(Action<SyncResponse> onSuccess, Action<string> onError);

        /// <summary>
        /// Получение оффлайн бонуса
        /// </summary>
        /// <param name="onSuccess">Callback с наградами</param>
        /// <param name="onError">Callback при ошибке</param>
        IEnumerator ClaimOfflineBonus(Action<OfflineRewards> onSuccess, Action<string> onError);
    }

    #region DTO Classes

    // Authentication
    [Serializable]
    public class AuthResponse
    {
        public string token;
        public int expiresIn;
        public PlayerInfo player;
    }

    [Serializable]
    public class PlayerInfo
    {
        public string playerId;
        public string nickname;
        public int level;
        public bool isNewPlayer;
    }

    // Tap System
    [Serializable]
    public class TapData
    {
        public long clientTimestamp;
        public Vector2Data screenPosition;
    }

    [Serializable]
    public class Vector2Data
    {
        public float x;
        public float y;

        public Vector2Data() { }

        public Vector2Data(Vector2 vec)
        {
            x = vec.x;
            y = vec.y;
        }
    }

    [Serializable]
    public class TapBatchResponse
    {
        public int validTapsCount;
        public int invalidTapsCount;
        public long wattsEarned;
        public long xpEarned;
        public PlayerResources resources;
        public List<TapEffect> effects;
        public LevelUpInfo levelUp;
    }

    [Serializable]
    public class TapEffect
    {
        public string type; // tap_success, combo, critical, level_up
        public Vector2Data position;
        public float value;
        public float multiplier;
    }

    [Serializable]
    public class LevelUpInfo
    {
        public int newLevel;
        public Rewards rewards;
    }

    // Sync
    [Serializable]
    public class SyncResponse
    {
        public PlayerResources resources;
        public OfflineRewards offlineRewards;
        public int hitsRecovered;
    }

    // Rewards
    [Serializable]
    public class OfflineRewards
    {
        public long wattsEarned;
        public int offlineDuration;
        public float multiplier;
        public int maxDuration;
    }

    [Serializable]
    public class Rewards
    {
        public long watts;
        public long xp;
        public string kiloWattTokens;
        public List<InventoryItem> items;
    }

    #endregion
}

using UnityEngine;

namespace WattsTap.Game.API
{
    /// <summary>
    /// ScriptableObject конфигурация для Mock API
    /// Позволяет настраивать поведение мока через Inspector
    /// </summary>
    [CreateAssetMenu(fileName = "MockAPIConfig", menuName = "WattsTap/API/Mock API Config")]
    public class MockAPIConfig : ScriptableObject
    {
        [Header("Network Simulation")]
        [Tooltip("Симулировать задержку сети")]
        public bool simulateNetworkDelay = true;

        [Tooltip("Минимальная задержка в секундах")]
        [Range(0f, 2f)]
        public float minDelay = 0.1f;

        [Tooltip("Максимальная задержка в секундах")]
        [Range(0f, 5f)]
        public float maxDelay = 0.5f;

        [Header("Error Simulation")]
        [Tooltip("Вероятность ошибки (0 = никогда, 1 = всегда)")]
        [Range(0f, 1f)]
        public float errorChance;

        [Tooltip("Типы ошибок для симуляции")]
        public ErrorType[] possibleErrors = new ErrorType[]
        {
            ErrorType.NetworkTimeout,
            ErrorType.ServerError,
            ErrorType.RateLimitExceeded
        };

        [Header("Mock Player Data")]
        [Tooltip("Начальное количество Watts")]
        public long startingWatts = 10000;

        [Tooltip("Начальный уровень игрока")]
        public int startingLevel = 5;

        [Tooltip("Начальное количество ударов")]
        public int startingHits = 18;

        [Tooltip("Максимальное количество ударов")]
        public int maxHits = 20;

        [Tooltip("Доход за тап")]
        public long incomePerTap = 50;

        [Tooltip("Пассивный доход в час")]
        public long incomePerHour = 1000;

        [Header("Offline Simulation")]
        [Tooltip("Симулировать время оффлайн (в часах)")]
        [Range(0f, 24f)]
        public float offlineHours = 1f;

        [Header("Gameplay Tweaks")]
        [Tooltip("Множитель опыта (для быстрого тестирования level up)")]
        [Range(1f, 10f)]
        public float xpMultiplier = 1f;

        [Tooltip("Автоматически давать level up при достижении XP")]
        public bool autoLevelUp = true;

        [Tooltip("Бесконечные удары (не тратятся при тапах)")]
        public bool infiniteHits;

        [Header("Logging")]
        [Tooltip("Выводить подробные логи в консоль")]
        public bool verboseLogging = true;

        [Tooltip("Показывать время ответа в логах")]
        public bool logResponseTime = true;

        public enum ErrorType
        {
            NetworkTimeout,
            ServerError,
            InvalidToken,
            RateLimitExceeded,
            InsufficientResources
        }

        public string GetRandomErrorMessage()
        {
            if (possibleErrors.Length == 0)
                return "Unknown error";

            var errorType = possibleErrors[Random.Range(0, possibleErrors.Length)];

            return errorType switch
            {
                ErrorType.NetworkTimeout => "Network timeout. Please check your connection.",
                ErrorType.ServerError => "Internal server error. Please try again later.",
                ErrorType.InvalidToken => "Invalid or expired authentication token.",
                ErrorType.RateLimitExceeded => "Rate limit exceeded. Please slow down.",
                ErrorType.InsufficientResources => "Insufficient resources to complete this action.",
                _ => "Unknown error occurred."
            };
        }
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using WattsTap.Game.Player;

namespace WattsTap.Game.API
{
    /// <summary>
    /// Mock-реализация API сервиса для тестирования в редакторе
    /// Симулирует серверные ответы без реального бэкенда
    /// </summary>
    public class WattsTapAPIMockService : IWattsTapAPIService
    {
        private string _authToken;
        private string _sessionId;
        private PlayerData _mockPlayerData;
        private int _tapCounter;
        private DateTime _lastLogoutTime;
        private MockAPIConfig _config;

        // Публичные поля для контроля из Editor Window
        public bool simulateNetworkDelay = true;
        public float minDelay = 0.1f;
        public float maxDelay = 0.5f;
        public float errorChance;

        public int InitializationOrder => 5;
        public bool IsInitialized { get; private set; }

        public WattsTapAPIMockService(MockAPIConfig config = null)
        {
            _config = config;
            if (_config != null)
            {
                simulateNetworkDelay = _config.simulateNetworkDelay;
                minDelay = _config.minDelay;
                maxDelay = _config.maxDelay;
                errorChance = _config.errorChance;
            }
        }

        public void Initialize()
        {
            _sessionId = Guid.NewGuid().ToString();

            // Устанавливаем время последнего выхода из конфига
            float offlineHours = _config != null ? _config.offlineHours : 1f;
            _lastLogoutTime = DateTime.UtcNow.AddHours(-offlineHours);

            InitializeMockPlayerData();

            IsInitialized = true;

            LogInfo($"Service initialized with session: {_sessionId}");
            LogInfo($"Network delay: {simulateNetworkDelay}, Error chance: {errorChance * 100}%");
        }

        public void Shutdown()
        {
            _authToken = null;
            _lastLogoutTime = DateTime.UtcNow;
            IsInitialized = false;
        }

        private void InitializeMockPlayerData()
        {
            long startingWatts = _config != null ? _config.startingWatts : 10000;
            int startingLevel = _config != null ? _config.startingLevel : 5;
            int startingHits = _config != null ? _config.startingHits : 18;
            int maxHits = _config != null ? _config.maxHits : 20;
            long incomePerTap = _config != null ? _config.incomePerTap : 50;
            long incomePerHour = _config != null ? _config.incomePerHour : 1000;

            _mockPlayerData = new PlayerData
            {
                playerId = Guid.NewGuid().ToString(),
                nickname = "MockPlayer",
                level = startingLevel,
                avatarUrl = "https://via.placeholder.com/150",
                telegramUserId = 123456789,
                tonWalletAddress = "",
                resources = new PlayerResources
                {
                    watts = startingWatts,
                    currentEnergy = 80,
                    maxEnergy = 100,
                    currentXP = 2500,
                    xpToNextLevel = CalculateXpForNextLevel(startingLevel),
                    kiloWattTokens = 0,
                    currentHits = startingHits,
                    maxHits = maxHits
                },
                stats = new PlayerStats
                {
                    totalTaps = 500,
                    totalPlayTimeSeconds = 3600,
                    incomePerHour = incomePerHour,
                    incomePerTap = incomePerTap,
                    friendsCount = 3,
                    upgradesPurchased = 5,
                    chestsOpened = 2,
                    tournamentRank = 0,
                    bestTournamentRank = 0,
                    lastLoginTime = DateTime.UtcNow
                },
                inventory = new InventoryData(),
                dailyLoginStreak = 3,
                lastDailyBonusDate = DateTime.UtcNow.AddDays(-1),
                createdAt = DateTime.UtcNow.AddDays(-30),
                updatedAt = DateTime.UtcNow
            };
        }

        // Аутентификация
        public IEnumerator Authenticate(string initData, Action<AuthResponse> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("Authentication", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            _authToken = $"mock_token_{Guid.NewGuid().ToString().Substring(0, 8)}";

            var response = new AuthResponse
            {
                token = _authToken,
                expiresIn = 86400,
                player = new PlayerInfo
                {
                    playerId = _mockPlayerData.playerId,
                    nickname = _mockPlayerData.nickname,
                    level = _mockPlayerData.level,
                    isNewPlayer = false
                }
            };

            LogSuccess("Authenticate", $"Authenticated as {response.player.nickname}", startTime);
            onSuccess?.Invoke(response);
        }

        // Отправка пакета тапов
        public IEnumerator SendTapBatch(List<TapData> taps, Action<TapBatchResponse> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("SendTapBatch", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            int validTaps = taps.Count;
            int invalidTaps = 0;

            // Проверяем доступность ударов (если не infinite mode)
            bool infiniteHits = _config != null && _config.infiniteHits;
            if (!infiniteHits && _mockPlayerData.resources.currentHits < validTaps)
            {
                validTaps = _mockPlayerData.resources.currentHits;
                invalidTaps = taps.Count - validTaps;
            }

            // Рассчитываем награды
            long wattsPerTap = _mockPlayerData.stats.incomePerTap;
            float xpMultiplier = _config != null ? _config.xpMultiplier : 1f;
            long xpPerTap = (long)(5 * xpMultiplier);
            long totalWatts = wattsPerTap * validTaps;
            long totalXp = xpPerTap * validTaps;

            // Обновляем ресурсы
            if (!infiniteHits)
            {
                _mockPlayerData.resources.currentHits -= validTaps;
            }
            _mockPlayerData.resources.watts += totalWatts;
            _mockPlayerData.resources.currentXP += totalXp;
            _mockPlayerData.stats.totalTaps += validTaps;
            _tapCounter += validTaps;

            // Проверяем level up
            LevelUpInfo levelUp = null;
            bool autoLevelUp = _config == null || _config.autoLevelUp;

            if (autoLevelUp && _mockPlayerData.resources.currentXP >= _mockPlayerData.resources.xpToNextLevel)
            {
                _mockPlayerData.level++;
                _mockPlayerData.resources.currentXP -= _mockPlayerData.resources.xpToNextLevel;
                _mockPlayerData.resources.xpToNextLevel = CalculateXpForNextLevel(_mockPlayerData.level);

                levelUp = new LevelUpInfo
                {
                    newLevel = _mockPlayerData.level,
                    rewards = new Rewards
                    {
                        watts = 1000,
                        xp = 0,
                        kiloWattTokens = null,
                        items = new List<InventoryItem>()
                    }
                };

                LogInfo($" LEVEL UP! New level: {_mockPlayerData.level}");
            }

            // Создаём эффекты
            var effects = new List<TapEffect>();
            for (int i = 0; i < Mathf.Min(validTaps, taps.Count); i++)
            {
                effects.Add(new TapEffect
                {
                    type = "tap_success",
                    position = taps[i].screenPosition,
                    value = wattsPerTap,
                    multiplier = 1.0f
                });
            }

            // Комбо каждые 5 тапов
            if (_tapCounter % 5 == 0 && validTaps > 0)
            {
                effects.Add(new TapEffect
                {
                    type = "combo",
                    position = taps[0].screenPosition,
                    value = 0,
                    multiplier = 1.2f
                });
            }

            var response = new TapBatchResponse
            {
                validTapsCount = validTaps,
                invalidTapsCount = invalidTaps,
                wattsEarned = totalWatts,
                xpEarned = totalXp,
                resources = CloneResources(_mockPlayerData.resources),
                effects = effects,
                levelUp = levelUp
            };

            LogSuccess("SendTapBatch", $"{validTaps} taps, +{totalWatts} watts, +{totalXp} XP", startTime);
            onSuccess?.Invoke(response);
        }

        // Получение данных игрока
        public IEnumerator GetPlayerData(Action<PlayerData> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("GetPlayerData", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            _mockPlayerData.updatedAt = DateTime.UtcNow;

            LogSuccess("GetPlayerData", $"Level {_mockPlayerData.level}, {_mockPlayerData.resources.watts} watts", startTime);
            onSuccess?.Invoke(ClonePlayerData(_mockPlayerData));
        }

        // Синхронизация состояния
        public IEnumerator SyncGameState(Action<SyncResponse> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("SyncGameState", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            // Восстанавливаем удары
            int hitsRecovered = Mathf.Min(
                _mockPlayerData.resources.maxHits - _mockPlayerData.resources.currentHits,
                5 // Восстанавливаем до 5 ударов
            );
            _mockPlayerData.resources.currentHits += hitsRecovered;

            var response = new SyncResponse
            {
                resources = CloneResources(_mockPlayerData.resources),
                offlineRewards = null,
                hitsRecovered = hitsRecovered
            };

            LogSuccess("SyncGameState", $"recovered {hitsRecovered} hits", startTime);
            onSuccess?.Invoke(response);
        }

        // Получение оффлайн бонуса
        public IEnumerator ClaimOfflineBonus(Action<OfflineRewards> onSuccess, Action<string> onError)
        {
            var startTime = Time.realtimeSinceStartup;
            yield return SimulateNetworkDelay();

            if (ShouldSimulateError())
            {
                LogError("ClaimOfflineBonus", GetErrorMessage());
                onError?.Invoke(GetErrorMessage());
                yield break;
            }

            var now = DateTime.UtcNow;
            var offlineDuration = (int)(now - _lastLogoutTime).TotalSeconds;
            var maxDuration = 4 * 3600; // 4 часа
            offlineDuration = Mathf.Min(offlineDuration, maxDuration);

            var incomePerHour = _mockPlayerData.stats.incomePerHour;
            var wattsEarned = (long)(incomePerHour * (offlineDuration / 3600f) * 1.5f); // 1.5x множитель

            _mockPlayerData.resources.watts += wattsEarned;
            _lastLogoutTime = now;

            var rewards = new OfflineRewards
            {
                wattsEarned = wattsEarned,
                offlineDuration = offlineDuration,
                multiplier = 1.5f,
                maxDuration = maxDuration
            };

            LogSuccess("ClaimOfflineBonus", $"+{wattsEarned} watts for {offlineDuration}s offline", startTime);
            onSuccess?.Invoke(rewards);
        }

        // Вспомогательные методы
        private IEnumerator SimulateNetworkDelay()
        {
            if (!simulateNetworkDelay)
                yield break;

            float delay = UnityEngine.Random.Range(minDelay, maxDelay);
            yield return new WaitForSeconds(delay);
        }

        private bool ShouldSimulateError()
        {
            return UnityEngine.Random.value < errorChance;
        }

        private string GetErrorMessage()
        {
            if (_config != null)
                return _config.GetRandomErrorMessage();

            return "Mock error: Request failed";
        }

        private long CalculateXpForNextLevel(int level)
        {
            return 1000 * level + 500 * (level - 1);
        }

        private PlayerData ClonePlayerData(PlayerData original)
        {
            // Простое клонирование через JSON (для мока достаточно)
            string json = JsonUtility.ToJson(original);
            return JsonUtility.FromJson<PlayerData>(json);
        }

        private PlayerResources CloneResources(PlayerResources original)
        {
            return new PlayerResources
            {
                watts = original.watts,
                currentEnergy = original.currentEnergy,
                maxEnergy = original.maxEnergy,
                currentXP = original.currentXP,
                xpToNextLevel = original.xpToNextLevel,
                kiloWattTokens = original.kiloWattTokens,
                currentHits = original.currentHits,
                maxHits = original.maxHits
            };
        }

        // Публичные методы для управления моком из редактора
        public void ResetPlayerData()
        {
            InitializeMockPlayerData();
            Debug.Log("[MockAPI] Player data reset");
        }

        public void AddWatts(long amount)
        {
            _mockPlayerData.resources.watts += amount;
            Debug.Log($"[MockAPI] Added {amount} watts. New balance: {_mockPlayerData.resources.watts}");
        }

        public void AddXp(long amount)
        {
            _mockPlayerData.resources.currentXP += amount;
            Debug.Log($"[MockAPI] Added {amount} XP. Current XP: {_mockPlayerData.resources.currentXP}");
        }

        public void SetLevel(int level)
        {
            _mockPlayerData.level = level;
            _mockPlayerData.resources.xpToNextLevel = CalculateXpForNextLevel(level);
            Debug.Log($"[MockAPI] Set level to {level}");
        }

        public void RestoreHits()
        {
            _mockPlayerData.resources.currentHits = _mockPlayerData.resources.maxHits;
            Debug.Log($"[MockAPI] Hits restored to {_mockPlayerData.resources.maxHits}");
        }

        public void SetErrorChance(float chance)
        {
            errorChance = Mathf.Clamp01(chance);
            Debug.Log($"[MockAPI] Error chance set to {errorChance * 100}%");
        }

        public PlayerData GetCurrentMockData()
        {
            return _mockPlayerData;
        }

        // Logging helpers
        private void LogInfo(string message)
        {
            if (_config == null || _config.verboseLogging)
            {
                Debug.Log($"[MockAPI] {message}");
            }
        }

        private void LogSuccess(string method, string message, float startTime)
        {
            if (_config == null || _config.verboseLogging)
            {
                string timeInfo = "";
                if (_config != null && _config.logResponseTime)
                {
                    float duration = (Time.realtimeSinceStartup - startTime) * 1000f;
                    timeInfo = $" ({duration:F0}ms)";
                }
                Debug.Log($"[MockAPI] ✓ {method}: {message}{timeInfo}");
            }
        }

        private void LogError(string method, string error)
        {
            Debug.LogError($"[MockAPI] ✗ {method}: {error}");
        }
    }
}

# Mock API - Руководство по использованию

##  Обзор

Mock API Service позволяет тестировать и разрабатывать игру в Unity Editor без реального бэкенда. Все серверные ответы симулируются локально с настраиваемыми параметрами.

##  Быстрый старт

### 1. Регистрация Mock сервиса

В `ApplicationEntry.cs` замените реальный API сервис на Mock:

```csharp
using WattsTap.Core.API;

public class ApplicationEntry : MonoBehaviour
{
    [SerializeField] private MockAPIConfig mockConfig; // Опционально

    private void Awake()
    {
        #if UNITY_EDITOR
            // В редакторе используем Mock
            ServiceLocator.Register<IWattsTapAPIService>(
                new WattsTapAPIMockService(mockConfig)
            );
        #else
            // В билде используем реальный API
            ServiceLocator.Register<IWattsTapAPIService>(
                new WattsTapAPIService()
            );
        #endif

        ServiceLocator.Instance.InitializeAll();
    }
}
```

### 2. Создание конфигурации (опционально)

1. В Project окне: `Right Click → Create → WattsTap → API → Mock API Config`
2. Настройте параметры в Inspector
3. Присвойте конфиг в ApplicationEntry

##  Использование Editor Window

### Открытие панели управления

`Menu: WattsTap → Mock API Control Panel`

### Возможности панели

#### Status Section
- **Service Status**: Показывает, запущен ли Mock сервис
- **Mode**: MOCK (редактор) или PRODUCTION (билд)

#### Player Data Section
Отображает текущее состояние игрока:
- Player ID, Nickname, Level
- Resources (Watts, XP, Hits, Energy)
- Statistics (Total Taps, Income, etc.)

#### Modify Resources Section
Быстрое изменение ресурсов:
- **Add Watts**: Добавить определенное количество Watts
- **Add XP**: Добавить опыт
- **Set Level**: Установить уровень игрока
- **Restore Hits**: Восстановить удары до максимума

#### Simulation Settings
Контроль поведения мока:
- **Simulate Network Delay**: Включить/выключить задержку сети
  - Min/Max Delay: Диапазон задержки (0-5 сек)
- **Error Chance**: Вероятность случайных ошибок (0-100%)
  - Полезно для тестирования error handling

#### Quick Actions
Быстрые действия для тестирования:
-  **Add 10K Watts**: +10,000 Watts
- ⚡ **Add 1K XP**: +1,000 XP
-  **Reset Player Data**: Сброс до начальных значений
- ❤️ **Restore Hits**: Восстановление ударов
-  **Level Up**: Повысить уровень на 1
-  **Add Million Watts**: +1,000,000 Watts

## ⚙️ MockAPIConfig параметры

### Network Simulation
- `simulateNetworkDelay` - Включить задержку сети
- `minDelay` / `maxDelay` - Диапазон задержки (секунды)

### Error Simulation
- `errorChance` - Вероятность ошибки (0.0 - 1.0)
- `possibleErrors` - Типы ошибок для симуляции
  - NetworkTimeout
  - ServerError
  - InvalidToken
  - RateLimitExceeded
  - InsufficientResources

### Mock Player Data
Начальные значения при инициализации:
- `startingWatts` - Стартовые Watts (default: 10,000)
- `startingLevel` - Начальный уровень (default: 5)
- `startingHits` / `maxHits` - Удары (default: 18/20)
- `incomePerTap` - Доход за тап (default: 50)
- `incomePerHour` - Пассивный доход (default: 1,000)

### Offline Simulation
- `offlineHours` - Симулировать время оффлайн (0-24 часа)

### Gameplay Tweaks
- `xpMultiplier` - Множитель опыта (1-10x)
  - Для быстрого тестирования level up
- `autoLevelUp` - Автоматический level up при достижении XP
- `infiniteHits` - Бесконечные удары (не тратятся)

### Logging
- `verboseLogging` - Подробные логи в консоль
- `logResponseTime` - Показывать время ответа в миллисекундах

##  Примеры использования

### Пример 1: Быстрое тестирование Level Up

```csharp
// Создайте MockAPIConfig asset
// Установите:
mockConfig.xpMultiplier = 10f;
mockConfig.autoLevelUp = true;

// Теперь при тапах XP будет начисляться в 10 раз быстрее
// Level up будет происходить автоматически
```

### Пример 2: Тестирование ошибок сети

```csharp
mockConfig.errorChance = 0.3f; // 30% ошибок
mockConfig.possibleErrors = new[] {
    MockAPIConfig.ErrorType.NetworkTimeout,
    MockAPIConfig.ErrorType.ServerError
};

// Теперь 30% запросов будут возвращать случайные ошибки
// Проверьте, что ваш UI правильно обрабатывает ошибки
```

### Пример 3: Тестирование медленной сети

```csharp
mockConfig.simulateNetworkDelay = true;
mockConfig.minDelay = 1f;
mockConfig.maxDelay = 3f;

// Все запросы будут иметь задержку 1-3 секунды
// Проверьте loading индикаторы и UX
```

### Пример 4: Тестирование оффлайн наград

```csharp
mockConfig.offlineHours = 4f; // Симулируем 4 часа оффлайн

// При старте игры и вызове ClaimOfflineBonus()
// Игрок получит награды за 4 часа
```

### Пример 5: Бесконечные ресурсы для UI тестирования

```csharp
mockConfig.infiniteHits = true;
mockConfig.startingWatts = 1000000;

// Удары не будут тратиться
// Много стартовых Watts для тестирования покупок
```

##  Программное управление

### Из кода можно управлять Mock сервисом:

```csharp
var mockService = ServiceLocator.Get<IWattsTapAPIService>() as WattsTapAPIMockService;

if (mockService != null)
{
    // Добавить ресурсы
    mockService.AddWatts(5000);
    mockService.AddXP(1000);

    // Изменить уровень
    mockService.SetLevel(10);

    // Восстановить удары
    mockService.RestoreHits();

    // Настроить симуляцию
    mockService.SetErrorChance(0.2f); // 20% ошибок
    mockService.simulateNetworkDelay = true;
    mockService.minDelay = 0.5f;
    mockService.maxDelay = 1.5f;

    // Сброс данных
    mockService.ResetPlayerData();

    // Получить текущие данные
    var playerData = mockService.GetCurrentMockData();
    Debug.Log($"Current level: {playerData.level}");
}
```

##  Best Practices

### 1. Используйте разные конфиги для разных сценариев

Создайте несколько конфигов:
- `MockAPI_Normal.asset` - Обычное тестирование
- `MockAPI_FastLevelUp.asset` - Быстрый XP для тестирования прогрессии
- `MockAPI_SlowNetwork.asset` - Медленная сеть
- `MockAPI_ErrorProne.asset` - Много ошибок для стресс-теста

### 2. Тестируйте разные состояния

```csharp
// Тест: новый игрок
mockService.ResetPlayerData();
mockService.SetLevel(1);
mockService.AddWatts(0);

// Тест: опытный игрок
mockService.SetLevel(50);
mockService.AddWatts(10000000);

// Тест: нет ресурсов
mockService.AddWatts(-mockService.GetCurrentMockData().resources.watts);
```

### 3. Комбинируйте с Unity Test Framework

```csharp
[Test]
public void TestTapBatch_WithInsufficientHits()
{
    var mockService = new WattsTapAPIMockService();
    mockService.Initialize();

    // Установить 0 ударов
    var playerData = mockService.GetCurrentMockData();
    playerData.resources.currentHits = 0;

    // Попробовать тапнуть
    bool errorOccurred = false;
    StartCoroutine(mockService.SendTapBatch(
        new List<TapData> { new TapData() },
        onSuccess: (response) => {
            Assert.AreEqual(0, response.validTapsCount);
        },
        onError: (error) => {
            errorOccurred = true;
        }
    ));
}
```

### 4. Логирование для дебага

```csharp
mockConfig.verboseLogging = true;
mockConfig.logResponseTime = true;

// Теперь в консоли будут подробные логи:
// [MockAPI] ✓ SendTapBatch: 5 taps, +250 watts, +25 XP (127ms)
```

##  Переключение между Mock и Real API

### Автоматическое (рекомендуется)

```csharp
#if UNITY_EDITOR
    var apiService = new WattsTapAPIMockService(mockConfig);
#else
    var apiService = new WattsTapAPIService();
#endif

ServiceLocator.Register<IWattsTapAPIService>(apiService);
```

### Через ScriptableObject флаг

```csharp
[CreateAssetMenu(menuName = "WattsTap/Build Config")]
public class BuildConfig : ScriptableObject
{
    public bool useMockAPI;
}

// В ApplicationEntry:
[SerializeField] private BuildConfig buildConfig;

if (buildConfig.useMockAPI)
{
    ServiceLocator.Register<IWattsTapAPIService>(new WattsTapAPIMockService());
}
else
{
    ServiceLocator.Register<IWattsTapAPIService>(new WattsTapAPIService());
}
```

##  Отладка

### Console логи

Mock API выводит цветные логи:
- ✓ (зеленый) - Успешный запрос
- ✗ (красный) - Ошибка
-  - Level Up
- ℹ️ - Информация

### Формат логов

```
[MockAPI] ✓ SendTapBatch: 10 taps, +500 watts, +50 XP (245ms)
[MockAPI]  LEVEL UP! New level: 6
[MockAPI] ✗ ClaimOfflineBonus: Network timeout. Please check your connection.
```

### Включение/выключение логов

```csharp
mockConfig.verboseLogging = false; // Отключить большинство логов
// Ошибки все равно будут выводиться
```

##  Продакшен

### Убедитесь перед билдом:

```csharp
// ❌ Плохо - Mock будет в билде
ServiceLocator.Register<IWattsTapAPIService>(new WattsTapAPIMockService());

// ✅ Хорошо - Conditional compilation
#if UNITY_EDITOR
    ServiceLocator.Register<IWattsTapAPIService>(new WattsTapAPIMockService());
#else
    ServiceLocator.Register<IWattsTapAPIService>(new WattsTapAPIService());
#endif
```

### Build Validation

Добавьте проверку в Build Pipeline:

```csharp
public class BuildValidator : IPreprocessBuildWithReport
{
    public int callbackOrder => 0;

    public void OnPreprocessBuild(BuildReport report)
    {
        var entry = FindObjectOfType<ApplicationEntry>();
        if (entry.IsUsingMockAPI())
        {
            throw new BuildFailedException("Mock API is enabled in production build!");
        }
    }
}
```

